def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    # Identify alive opponents and their yesterday bids
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        # If alone, spend enough to secure water but not blow budget
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Pressure proxy: highest bid yesterday among survivors
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Determine urgency by supply: fewer units means more competition
    # Each agent needs 13 water; higher supply reduces urgency.
    # Use thresholding without relying on exact equilibrium.
    if supply <= float(WATER_REQ) + 1.0:
        urgency = 1.0
    elif supply <= float(WATER_REQ) + 4.0:
        urgency = 0.7
    else:
        urgency = 0.45

    # If opponents were bidding near/above our salary, they are likely fighting for survival.
    # We counter with a bid slightly above their typical high pressure when urgency is high.
    budget = float(my_status.get('budget', 0.0))
    hp = int(my_status.get('hp', 0))

    # Baseline target bid
    # - If high pressure yesterday: bid around (highest_prev_bid + small increment) scaled by urgency.
    # - Else: bid around a fraction of salary scaled by urgency.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        target = (highest_prev_bid + 2.0) * (0.65 + 0.35 * urgency)
    elif highest_prev_bid >= DAILY_SALARY * 0.6:
        target = (highest_prev_bid + 1.0) * (0.55 + 0.45 * urgency)
    else:
        target = DAILY_SALARY * (0.45 + 0.35 * urgency)

    # If our hp is low, increase bid to avoid death.
    if hp <= 2:
        target *= 1.25
    elif hp <= 3:
        target *= 1.12

    # Keep a floor so we don't underbid in tight supply; keep a cap so we don't bankrupt.
    # Use daily_salary multiples as safe bounds.
    min_bid = DAILY_SALARY * (0.35 + 0.25 * urgency)
    max_bid = DAILY_SALARY * (0.95 if hp <= 3 else 0.75)

    target = max(min_bid, min(max_bid, target))

    # Final: cannot exceed budget
    if budget <= 0:
        return 0.0
    return float(min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    rich_aggressive = 0
    desperate_opponents = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
                desperate_opponents += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = float(prev['bid'])
                prev_bids.append(bid)
                if bid >= DAILY_SALARY * 1.0 and opp.get('budget', 0) >= DAILY_SALARY * 4:
                    rich_aggressive += 1

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, DAILY_SALARY * 0.35))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    competitors = len(alive_opponents) + 1
    expected_units = supply / float(WATER_REQ)
    scarcity = competitors - expected_units

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1

    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 1

    if scarcity > 2.0:
        danger += 2
    elif scarcity > 1.0:
        danger += 1

    if supply >= 23:
        base = DAILY_SALARY * 0.28
    elif supply >= 20:
        base = DAILY_SALARY * 0.38
    elif supply >= 17:
        base = DAILY_SALARY * 0.52
    else:
        base = DAILY_SALARY * 0.68

    if rich_aggressive >= 2 and danger <= 2:
        base *= 0.72
    elif rich_aggressive >= 1 and danger <= 1:
        base *= 0.82

    if desperate_opponents >= 2:
        base += 8

    if day >= 8 and hp <= 5:
        base += 10

    if danger >= 5:
        bid = max(base, highest_prev + 2.0 if highest_prev > 0 else DAILY_SALARY * 0.92)
        bid = min(bid, DAILY_SALARY * 1.25)
    elif danger >= 3:
        target = max(avg_prev + 2.0, DAILY_SALARY * 0.62)
        if highest_prev >= DAILY_SALARY * 1.15:
            target = max(target, DAILY_SALARY * 0.88)
        bid = max(base, target)
        bid = min(bid, DAILY_SALARY * 1.05)
    else:
        if highest_prev >= DAILY_SALARY * 1.2:
            bid = min(base, DAILY_SALARY * 0.42)
        elif highest_prev >= DAILY_SALARY * 0.9:
            bid = min(max(base, DAILY_SALARY * 0.45), DAILY_SALARY * 0.6)
        else:
            bid = max(base, highest_prev + 1.5 if highest_prev > 0 else base)
            bid = min(bid, DAILY_SALARY * 0.72)

    if budget < DAILY_SALARY * 1.2 and danger <= 2:
        bid = min(bid, budget * 0.55)

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, DAILY_SALARY * 0.95)

    bid = max(0.0, min(float(bid), float(budget)))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    # Get alive opponents
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        # No competition, bid minimal to get water
        return min(my_status['budget'], max(1, DAILY_SALARY * 0.1))

    # Extract previous bids from yesterday's trace
    prev_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            bid_val = prev['bid']
            # Ensure it's a number
            if isinstance(bid_val, (int, float)):
                prev_bids.append(bid_val)

    highest_prev = max(prev_bids) if prev_bids else 0

    hp = my_status['hp']
    budget = my_status['budget']

    # If we are desperate for water (HP <= 2), bid aggressively
    if hp <= 2:
        needed = max(DAILY_SALARY * 0.9, highest_prev + 1.5)
        return min(budget, needed)

    # If HP is moderate (3-5), bid slightly above highest previous to secure water
    if hp <= 5:
        needed = max(DAILY_SALARY * 0.6, highest_prev + 0.5)
        return min(budget, needed)

    # If HP is high, we can save money: bid low, but ensure we beat opponents' lowest habits
    # Use a fraction of daily salary, but not too low to risk losing water when we don't need it
    # Actually, we can afford to lose some days, so bid conservatively
    low_bid = DAILY_SALARY * 0.3
    # But if opponents bid low recently, we should still be safe
    return min(budget, low_bid)

